/* Lot 94: every gradient the reader writes in test_lot94_bgval.c, read by the engine (generated by scripts/lot94_gradgen.py; expectations from scripts/lot94_gradmodel.py). */

#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "webeng.h"

static we_doc_t g_doc;
static char g_html[1024];

static const we_node_t *g_n;

/* sets g_n to the engine's node for a div with background-image v */
static void eng(const char *v) {
    int i, idx;
    snprintf(g_html, sizeof(g_html), "<html><body><div id=t style='height:4px;background-image:%s'></div></body></html>", v);
    memset(&g_doc, 0, sizeof(g_doc));
    TEST_ASSERT_EQUAL(0, we_parse(&g_doc, g_html, (int)strlen(g_html)));
    TEST_ASSERT_EQUAL(0, we_style(&g_doc));
    for (i = 0; i < (int)g_doc.ndiag; i++) TEST_ASSERT(strstr(g_doc.diag[i], "refused") == 0);
    idx = we_find_id(&g_doc, "t");
    TEST_ASSERT(idx >= 0);
    g_n = &g_doc.nodes[idx];
}

static void check(const char *v, int dir, int angle, int corner, int stops) {
    const we_node_t *n;
    g_n = 0;
    eng(v);
    TEST_ASSERT(g_n != 0);
    if (!g_n) return;
    n = g_n;
    TEST_ASSERT_EQUAL(dir, n->grad_dir);
    TEST_ASSERT_EQUAL(angle, n->grad_angle * 100 + n->grad_frac);   /* Lot 96: 1/100 degree */
    TEST_ASSERT_EQUAL(corner, n->grad_corner);
    TEST_ASSERT_EQUAL(stops, n->grad_count);
}

